function whatThePh() {
  const pts = Array.from({ length: 10 }, (_, i) => { const a = i / 10 * Math.PI * 2; return [50 + Math.cos(a) * 22 + Math.sin(i * 7) * 3, 58 + Math.sin(a) * 26 + Math.cos(i * 5) * 3]; });
  return banner({ bg: WHITE, tint: '#eef6fa', scan: true },
    pts.map(([x, y], i) => box('<div class="ph-ball"></div>', { x, y, w: 1, z: 1, cls: 'ph-grow', style: `--i:${i}` })).join(''),
    pts.map(([x, y], i) => pane('marble', { x, y, w: 7, anim: 'bob', dur: 2.5 + (i % 3) * .4, delay: -i * .3, amp: .3, z: 2 })).join(''),
    wtitle('what the ph', { x: 50, y: 15, size: 9 }));
}

function annagram() {
  const L = 'annagram'.split('').map((c, i) => `<span style="--i:${i}">${c}</span>`).join('');
  return banner({ bg: WHITE, tint: '#f5eef3', scan: true },
    pane('bubble', { x: 50, y: 57, w: 62, anim: 'pulse', dur: 3, reflect: false }),
    box(`<div class="ag">${L}</div>`, { x: 50, y: 52, w: 60, z: 3 }),
    sparkles(8, { x0: 10, x1: 90, y0: 10, y1: 90, color: '#f06aa8', seed: 9 }));
}

