function snridworld() {
  // a dense field of dim ascii ground on black, the way the garden itself is drawn
  let seed = 41; const r = () => (seed = (seed * 16807) % 2147483647) / 2147483647;
  const G = '.,:;\'`"*%&#@^v~-=+o', COL = ['#6b5a2e', '#8a6a2a', '#4d6b34', '#7a4a3a', '#5a5a52', '#a07a3a', '#3f5a3a', '#8a5a6a'];
  const rows = Array.from({ length: 14 }, () => Array.from({ length: 40 }, () => {
    const v = r(); return v < .18 ? ' ' : `<i style="color:${COL[Math.floor(r() * COL.length)]};opacity:${(.35 + r() * .55).toFixed(2)}">${G[Math.floor(r() * G.length)]}</i>`;
  }).join('')).join('<br>');
  return banner({ bg: '#07080a', tint: '#0d0f0c' },
    `<div class="sn-field">${rows}</div>`,
    pane('strawberry', { x: 14, y: 34, w: 11, rot: -10 }),
    pane('leaf', { x: 86, y: 30, w: 17, rot: 24, anim: 'sway', dur: 5, amp: .4 }),
    pane('cucumber', { x: 84, y: 80, w: 14 }),
    pane('snail', { x: 50, y: 68, w: 28, anim: 'crawl', dur: 16, amp: .45 }),
    box('<div class="ascii">_(@)"</div>', { x: 50, y: 15, w: 40, anim: 'bob', dur: 2 }),
    wtitle('snridworld', { x: 50, y: 37, size: 8, dark: true }));
}

function brezvax() {
  const T = { x: .49, y: .345, w: .38, h: .36 };   // the screen in img/terminal.webp, measured by colour
  const lines = ['brezvax!login: guest', 'Welcome to brezvax.', '% rn net.general', '% tip arpa'];
  return banner({ bg: 'radial-gradient(100% 120% at 50% 30%, #2a3a30 0, #0d140f 80%)', tint: '#1a2a1e' },
    box(`<div class="term"><img src="img/terminal.webp" alt=""><div class="tscr" style="left:${(T.x - T.w / 2) * 100}%;top:${(T.y - T.h / 2) * 100}%;width:${T.w * 100}%;height:${T.h * 100}%">${lines.map((l, i) => `<p style="--i:${i}">${l}</p>`).join('')}<p class="cur">█</p></div></div>`, { x: 50, y: 54, w: 56 }));
}

export const WII_ART = { recursite, notbell, annasArxiv, honeypot, whatThePh, annagram, stochasticShore, bukvarium, brezgiLv, snowGlobe, dinoTrain, grotte, namedayParty, corporaCafe, petroglyphs, flockquarium, flyParadise, noosphere, lavaHash, ancientClub, soundscapade, snridworld, brezvax };
